export function foundationPresentation(kind:FoundationKind,index:number,progress:number,elapsed:number){const p=foundationDefaults(kind);if(kind==='cellstructure'){p.ub=[0,1,2,4,0][index];p.uc=index===3?1:0}if(kind==='geneticcode'){p.ua=index<2?0:index===2?1:2;p.ub=index===4?1:0}if(kind==='planttransport'){p.uc=[0,1,2,2,0][index]}if(kind==='ecosystem')p.uc=index<2?0:1;const phase=((elapsed%6)+6)%6/6;if(kind==='animals')p.ua=[0,1,2,3,0][index];if(kind==='senses')p.ua=index;if(kind==='food')p.ua=index%4;if(kind==='safety')p.ua=[0,0,1,2,3][index];if(kind==='waterstates'){p.ua=[-10,0,25,100,110][index];p.ub=phase}if(kind==='force'&&index===1)p.ua=-5;if(kind==='shadow'){if(index===3)p.ua=-.8+progress*1.6;if(index===4)p.ub=.15+progress*.35}if(kind==='sound')p.ua=[100,200,200,200,400][index];if(kind==='daynight')p.ub=phase*24;if(kind==='measurement'&&index===3)p.uc=20;if(kind==='robot'&&index===4)p.uc=.1;return{p,time:elapsed}}
